531	bool ValidateStationCatalog(const StationCatalog& catalog, std::string* message) {
532	  if (catalog.stations.empty()) {
533	    if (message != nullptr) {
534	      *message = "station catalog is empty";
535	    }
536	    return false;
537	  }
538	
539	  std::unordered_set<std::string> ids;
540	  for (const auto& station : catalog.stations) {
541	    if (station.id.empty()) {
542	      if (message != nullptr) {
543	        *message = "station id is empty";
544	      }
545	      return false;
546	    }
547	    if (station.frame_id.empty()) {
548	      if (message != nullptr) {
549	        *message = "station frame_id is empty: " + station.id;
550	      }
551	      return false;
552	    }
553	    if (!std::isfinite(station.x) || !std::isfinite(station.y) || !std::isfinite(station.yaw)) {
554	      if (message != nullptr) {
555	        *message = "station pose is not finite: " + station.id;
556	      }
557	      return false;
558	    }
559	    if (!ids.insert(station.id).second) {
560	      if (message != nullptr) {
561	        *message = "duplicate station id: " + station.id;
562	      }
563	      return false;
564	    }
565	  }
566	
567	  // road_nodes 与 stations 共用同一 id 空间：集合内与跨集合均不允许重复
568	  for (const auto& road_node : catalog.road_nodes) {
569	    if (road_node.id.empty()) {
570	      if (message != nullptr) {
571	        *message = "road node id is empty";
572	      }
573	      return false;
574	    }
575	    if (road_node.frame_id.empty()) {
576	      if (message != nullptr) {
577	        *message = "road node frame_id is empty: " + road_node.id;
578	      }
579	      return false;
580	    }
581	    if (!std::isfinite(road_node.x) || !std::isfinite(road_node.y) ||
582	        !std::isfinite(road_node.yaw)) {
583	      if (message != nullptr) {
584	        *message = "road node pose is not finite: " + road_node.id;
585	      }
586	      return false;
587	    }
588	    if (!ids.insert(road_node.id).second) {
589	      if (message != nullptr) {
590	        *message = "duplicate road node id: " + road_node.id;
591	      }
592	      return false;
593	    }
594	  }
595	
596	  for (const auto& edge : catalog.edges) {
597	    if (edge.from.empty() || edge.to.empty()) {
598	      if (message != nullptr) {
599	        *message = "station edge endpoint is empty";
600	      }
601	      return false;
602	    }
603	    if (ids.find(edge.from) == ids.end()) {
604	      if (message != nullptr) {
605	        *message = "station edge has unknown from endpoint: " + edge.from;
606	      }
607	      return false;
608	    }
609	    if (ids.find(edge.to) == ids.end()) {
610	      if (message != nullptr) {
611	        *message = "station edge has unknown to endpoint: " + edge.to;
612	      }
613	      return false;
614	    }
615	    if (!std::isfinite(edge.distance_m) || edge.distance_m < 0.0) {
616	      if (message != nullptr) {
617	        *message = "station edge distance is invalid: " + edge.from + " -> " + edge.to;
618	      }
619	      return false;
620	    }
621	    for (const auto& point : edge.polyline) {
622	      if (!std::isfinite(point.first) || !std::isfinite(point.second)) {
623	        if (message != nullptr) {
624	          *message = "station edge polyline point is not finite: " + edge.from + " -> " + edge.to;
625	        }
626	        return false;
627	      }
628	    }
629	  }
630	
631	  if (message != nullptr) {
632	    *message = "ok";
633	  }
634	  return true;
635	}
