674	StationCatalogReloader::StationCatalogReloader(std::filesystem::path path)
675	    : path_(std::move(path)),
676	      watcher_(path_.string(), [this](const YAML::Node&) { TryLoad(true); }) {
677	  TryLoad(false);   // 初始加载等价节点 on_configure 的一次性读取
678	  watcher_.Tick();  // 建立 mtime 基线：首拍只记基线不回调，之后的变化才重载
679	}
680	
681	bool StationCatalogReloader::Tick() {
682	  const auto before = reload_count_;
683	  watcher_.Tick();
684	  if (!watcher_.last_error().empty()) {
685	    last_error_ = watcher_.last_error();  // YAML 解析失败：回调未触发，旧目录保持
686	  }
687	  return reload_count_ > before;
688	}
689	
690	std::string StationCatalogReloader::last_error() const {
691	  return last_error_;
692	}
693	
694	void StationCatalogReloader::TryLoad(bool count_as_reload) {
695	  if (auto loaded = LoadStationCatalog(path_)) {
696	    catalog_ = std::move(*loaded);
697	    loaded_ = true;
698	    if (count_as_reload) {
699	      ++reload_count_;
700	    }
701	    last_error_.clear();
702	  } else {
703	    // 校验失败（空目录、重复 id、非法位姿等）：保留旧目录，记录错误
704	    last_error_ = "station catalog invalid or unreadable: " + path_.string();
705	  }
706	}
