18	// 8 邻域方向（顺时针，自正北起）：与 skeleton_extractor 保持一致。
19	constexpr int kDRow[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
20	constexpr int kDCol[8] = {0, 1, 1, 1, 0, -1, -1, -1};
21	
22	// 像素坐标（整数栅格）。
23	struct Pixel {
24	  int col = 0;
25	  int row = 0;
26	
27	  bool operator==(const Pixel& other) const {
28	    return col == other.col && row == other.row;
29	  }
30	};
31	
32	struct PixelHash {
33	  size_t operator()(const Pixel& p) const {
34	    return (static_cast<size_t>(static_cast<uint32_t>(p.col)) << 32) ^
35	           static_cast<size_t>(static_cast<uint32_t>(p.row));
36	  }
37	};
