39	// 8 邻域环上的连通组数（P2..P9,P2 环状序列中 0→1 跳变次数）：
40	//   0 = 孤立，1 = 端点，2 = 中段，>= 3 = 分叉。
41	// 与 skeleton_extractor.cpp 中 CrossingNumber 完全相同的判据。
42	int CrossingNumber(const BinaryGrid& grid, int col, int row) {
43	  int neighbors[8];
44	  int B = 0;
45	  for (int i = 0; i < 8; ++i) {
46	    neighbors[i] = grid.GetValue(col + kDCol[i], row + kDRow[i]) ? 1 : 0;
47	    B += neighbors[i];
48	  }
49	  if (B == 0) {
50	    return 0;
51	  }
52	  if (B == 8) {
53	    return 1;
54	  }
55	  int groups = 0;
56	  for (int i = 0; i < 8; ++i) {
57	    if (!neighbors[i] && neighbors[(i + 1) % 8]) {
58	      ++groups;
59	    }
60	  }
61	  return groups;
62	}
63	
64	// 折线累加长度：相邻折线点间欧氏距离之和。
65	double PolylineLength(const std::vector<std::pair<double, double>>& polyline) {
66	  double total = 0.0;
67	  for (size_t i = 1; i < polyline.size(); ++i) {
68	    const double dx = polyline[i].first - polyline[i - 1].first;
69	    const double dy = polyline[i].second - polyline[i - 1].second;
70	    total += std::hypot(dx, dy);
71	  }
72	  return total;
73	}
