75	// 点 P 到线段 AB 的最近点（垂足或端点）。
76	// 返回 (proj_x, proj_y, dist, t)，t 在 [0,1] 表示投影参数位置。
77	std::pair<std::pair<double, double>, double> ProjectPointToSegment(
78	    double px, double py, double ax, double ay, double bx, double by,
79	    double* t_out) {
80	  const double abx = bx - ax;
81	  const double aby = by - ay;
82	  const double apx = px - ax;
83	  const double apy = py - ay;
84	  const double ab_len_sq = abx * abx + aby * aby;
85	  double t = 0.0;
86	  if (ab_len_sq > 0.0) {
87	    t = (apx * abx + apy * aby) / ab_len_sq;
88	    t = std::max(0.0, std::min(1.0, t));
89	  }
90	  const double qx = ax + t * abx;
91	  const double qy = ay + t * aby;
92	  const double dist = std::hypot(px - qx, py - qy);
93	  if (t_out != nullptr) {
94	    *t_out = t;
95	  }
96	  return {{qx, qy}, dist};
97	}
