99	// ---- 骨架图追踪 -------------------------------------------------------------
100	
101	// 内部图边（像素域）：from/to 为节点像素，polyline_px 为从 from 到 to 的
102	// 像素序列（含两端节点）。在生成 CatalogStationEdge 时再统一转世界坐标。
103	struct PixelEdge {
104	  Pixel from;
105	  Pixel to;
106	  std::vector<Pixel> polyline_px;
107	};
108	
109	// 提取所有骨架特征点（crossing != 2 的像素）。返回特征点集合。
110	std::vector<Pixel> ExtractFeaturePixels(const BinaryGrid& skeleton) {
111	  std::vector<Pixel> features;
112	  for (uint32_t row = 0; row < skeleton.height; ++row) {
113	    for (uint32_t col = 0; col < skeleton.width; ++col) {
114	      const int c = static_cast<int>(col);
115	      const int r = static_cast<int>(row);
116	      if (!skeleton.GetValue(c, r)) {
117	        continue;
118	      }
119	      const int crossings = CrossingNumber(skeleton, c, r);
120	      if (crossings != 2) {
121	        features.push_back({c, r});
122	      }
123	    }
124	  }
125	  return features;
126	}
127	
128	// 单步推进：从 prev -> cur，返回所有可能的下一像素（除 prev 之外的骨架
129	// 邻居）。返回的下一像素若仍是中段（crossing==2）需要继续推进。
130	std::vector<Pixel> NextPixels(const BinaryGrid& skeleton, const Pixel& prev,
131	                              const Pixel& cur) {
132	  std::vector<Pixel> next;
133	  for (int i = 0; i < 8; ++i) {
134	    const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
135	    if (nb == prev) {
136	      continue;
137	    }
138	    if (skeleton.GetValue(nb.col, nb.row)) {
139	      next.push_back(nb);
140	    }
141	  }
142	  return next;
143	}
144	
145	// 在多候选下一像素中选择主续像素：
146	//   1. 优先选不在当前链中的像素（避免回环自相交）；
147	//   2. 其中选与来向 (cur - prev) 点积最大者（直线延续优先于斜向逃逸）。
148	// 这处理 1 像素宽骨架在 8 邻域下的"环上相邻"情况：L 形拐角内侧像素
149	// 会有 3 个骨架邻居（prev、内侧对角、正前方），ring 连通组仍为 2，
150	// 必须靠方向选择走出拐角而不是误判为分叉。
151	Pixel PickNextPixel(const Pixel& prev, const Pixel& cur,
152	                    const std::vector<Pixel>& nexts,
153	                    const std::unordered_set<Pixel, PixelHash>& chain_set) {
154	  const int dir_col = cur.col - prev.col;
155	  const int dir_row = cur.row - prev.row;
156	  Pixel best{-1, -1};
157	  double best_cos = -std::numeric_limits<double>::infinity();
158	  bool best_fresh = false;
159	  for (const Pixel& nb : nexts) {
160	    const bool fresh = chain_set.count(nb) == 0;
161	    const int step_col = nb.col - cur.col;
162	    const int step_row = nb.row - cur.row;
163	    const double step_len =
164	        (step_col == 0 || step_row == 0) ? 1.0 : std::sqrt(2.0);
165	    const double cos_angle =
166	        (dir_col * step_col + dir_row * step_row) / step_len;
167	    // 未访问优先；并列时按方向余弦。
168	    if (best.col == -1 || (fresh && !best_fresh) ||
169	        (fresh == best_fresh && cos_angle > best_cos)) {
170	      best = nb;
171	      best_cos = cos_angle;
172	      best_fresh = fresh;
173	    }
174	  }
175	  return best;
176	}
177	
178	// 从起点 start 沿邻居 first_step 方向追踪，直到抵达下一个特征点。
179	// 返回包含 start、所有中间像素、终止特征点的完整链。
180	// 若 first_step 本身即特征点，则链长为 2。
181	// 若链成环回到起点（无其他特征点），返回空——由外层做闭合环处理。
182	std::vector<Pixel> TraceFromToFeature(
183	    const BinaryGrid& skeleton, const Pixel& start, const Pixel& first_step,
184	    const std::unordered_set<Pixel, PixelHash>& feature_set) {
185	  std::vector<Pixel> chain;
186	  chain.push_back(start);
187	  chain.push_back(first_step);
188	  std::unordered_set<Pixel, PixelHash> chain_set;
189	  chain_set.insert(start);
190	  chain_set.insert(first_step);
191	
192	  Pixel prev = start;
193	  Pixel cur = first_step;
194	  const size_t max_steps =
195	      static_cast<size_t>(skeleton.width) * skeleton.height + 1;
196	  while (chain.size() <= max_steps) {
197	    // 当前点若是特征点（且不是起点本身），停止。
198	    if (!(cur == start) && feature_set.count(cur) > 0) {
199	      return chain;
200	    }
201	    // 中段：在非 prev 邻居中挑选主续方向（避免 8 邻域内侧角点误判分叉）。
202	    const std::vector<Pixel> nexts = NextPixels(skeleton, prev, cur);
203	    if (nexts.empty()) {
204	      return chain;  // 死胡同
205	    }
206	    const Pixel next = PickNextPixel(prev, cur, nexts, chain_set);
207	    if (next.col == -1) {
208	      return chain;
209	    }
210	    prev = cur;
211	    cur = next;
212	    chain.push_back(cur);
213	    chain_set.insert(cur);
214	    // 闭合回到起点：返回当前链（标记为环）
215	    if (cur == start) {
216	      return chain;
217	    }
218	  }
219	  return chain;
220	}
221	
222	// ---- 投影与边拆分 -----------------------------------------------------------
223	
224	// 在 edge.polyline（世界坐标）上找点 (px,py) 的最近投影点。
225	// 返回 (proj_x, proj_y, distance, segment_index, segment_t)
226	struct ProjectionResult {
227	  double px = 0.0;
228	  double py = 0.0;
229	  double distance = std::numeric_limits<double>::infinity();
230	  size_t segment_index = 0;  // 所在折线段索引（[i, i+1]）
231	  double segment_t = 0.0;    // 段内参数 [0,1]
232	};
233	
234	ProjectionResult ProjectToPolyline(
235	    double px, double py,
236	    const std::vector<std::pair<double, double>>& polyline) {
237	  ProjectionResult best;
238	  if (polyline.size() < 2) {
239	    return best;
240	  }
241	  for (size_t i = 0; i + 1 < polyline.size(); ++i) {
242	    double t = 0.0;
243	    const auto& a = polyline[i];
244	    const auto& b = polyline[i + 1];
245	    const auto proj = ProjectPointToSegment(px, py, a.first, a.second, b.first,
246	                                            b.second, &t);
247	    if (proj.second < best.distance) {
248	      best.px = proj.first.first;
249	      best.py = proj.first.second;
250	      best.distance = proj.second;
251	      best.segment_index = i;
252	      best.segment_t = t;
253	    }
254	  }
255	  return best;
256	}
257	
258	}  // namespace
259	
260	TopologyBuildResult BuildTopologyCatalog(
261	    const BinaryGrid& skeleton, const MapGrid& map_info,
262	    const std::vector<AnchorStation>& anchors,
263	    const TopologyBuilderConfig& config) {
264	  TopologyBuildResult result;
265	  catalog::StationCatalog& catalog = result.catalog;
266	  catalog.map_hash = config.map_hash;
267	  catalog.graph_version = config.graph_version;
268	
269	  if (skeleton.width == 0 || skeleton.height == 0) {
270	    result.error_message = "skeleton is empty";
271	    return result;
272	  }
273	
274	  // ---- 第一步：提取特征点并分配 RoadNode id ----
275	  const std::vector<Pixel> feature_pixels = ExtractFeaturePixels(skeleton);
276	  std::unordered_set<Pixel, PixelHash> feature_set(feature_pixels.begin(),
277	                                                   feature_pixels.end());
278	
279	  // 像素 -> RoadNode id 映射
280	  std::unordered_map<Pixel, std::string, PixelHash> pixel_to_node_id;
281	  std::unordered_map<Pixel, size_t, PixelHash> pixel_to_node_index;
282	  int next_node_idx = 0;
283	  for (const Pixel& p : feature_pixels) {
284	    const WorldCoord w =
285	        PixelToWorld(PixelCoord{static_cast<double>(p.col),
286	                                static_cast<double>(p.row)},
287	                     map_info);
288	    catalog::RoadNode node;
289	    node.id = "rn_" + std::to_string(p.col) + "_" + std::to_string(p.row);
290	    node.x = w.x;
291	    node.y = w.y;
292	    catalog.road_nodes.push_back(node);
293	    pixel_to_node_id[p] = node.id;
294	    pixel_to_node_index[p] = catalog.road_nodes.size() - 1;
295	    (void)next_node_idx;
296	    ++next_node_idx;
297	  }
298	
299	  // ---- 第二步：从每个特征点的每个邻居方向追踪，提取像素边 ----
300	  // visited_directed_edge：(from_node, first_step_pixel) 标记该方向是否已追踪。
301	  // 同一条无向边 (A,m1,...,B) 会被两端各追踪一次，用 (from_node, first_step)
302	  // 去重——注意反向追踪时 first_step 是该边在 B 端的最后中间像素，与正向
303	  // 的 first_step 不同，因此需要额外检查边是否已存在。
304	  std::vector<PixelEdge> pixel_edges;
305	  std::unordered_set<Pixel, PixelHash> visited_middle;
306	
307	  for (const Pixel& start : feature_pixels) {
308	    // 收集起点的所有骨架邻居
309	    std::vector<Pixel> neighbors;
310	    for (int i = 0; i < 8; ++i) {
311	      const Pixel nb{start.col + kDCol[i], start.row + kDRow[i]};
312	      if (skeleton.GetValue(nb.col, nb.row)) {
313	        neighbors.push_back(nb);
314	      }
315	    }
316	    for (const Pixel& first_step : neighbors) {
317	      // 若 first_step 已被访问且不是特征点，说明该方向上的边已被处理
318	      // （来自对端或同端的另一个起点方向）。
319	      if (feature_set.count(first_step) == 0 &&
320	          visited_middle.count(first_step) > 0) {
321	        continue;
322	      }
323	      // 检查边是否已被反向追踪（first_step 的对端像素对应）。
324	      // 简单做法：直接追踪，事后通过 (from_id,to_id,polyline) 三元组去重。
325	      std::vector<Pixel> chain =
326	          TraceFromToFeature(skeleton, start, first_step, feature_set);
327	      if (chain.size() < 2) {
328	        continue;
329	      }
330	      // 标记中间像素为已访问（特征点除外）。
331	      for (size_t i = 1; i + 1 < chain.size(); ++i) {
332	        visited_middle.insert(chain[i]);
333	      }
334	      PixelEdge pe;
335	      pe.from = chain.front();
336	      pe.to = chain.back();
337	      pe.polyline_px = chain;
338	      pixel_edges.push_back(std::move(pe));
339	    }
340	  }
341	
342	  // 处理孤立闭合环：未被任何边覆盖的骨架像素（无任何特征点的纯环）。
343	  // 遍历所有骨架像素，若某像素既不在 visited_middle 也不是 feature，则
344	  // 说明它属于某个未被追踪的闭合环。在环上任取一点作为 RoadNode，并把
345	  // 整条环像素序列作为一条"自环"边（from=to=该节点）——但 stations.yaml
346	  // schema 不允许 from==to，改为在环上任取两个像素作为 RoadNode，环切成
347	  // 两段边。
348	  {
349	    std::unordered_set<Pixel, PixelHash> covered;
350	    for (const PixelEdge& e : pixel_edges) {
351	      for (const Pixel& p : e.polyline_px) {
352	        covered.insert(p);
353	      }
354	    }
355	    // 收集所有未被覆盖的骨架像素
356	    std::vector<Pixel> orphan;
357	    for (uint32_t row = 0; row < skeleton.height; ++row) {
358	      for (uint32_t col = 0; col < skeleton.width; ++col) {
359	        const Pixel p{static_cast<int>(col), static_cast<int>(row)};
360	        if (skeleton.GetValue(p.col, p.row) && covered.count(p) == 0) {
361	          orphan.push_back(p);
362	        }
363	      }
364	    }
365	    // BFS 分组各连通环
366	    std::unordered_set<Pixel, PixelHash> visited_orphan;
367	    for (const Pixel& seed : orphan) {
368	      if (visited_orphan.count(seed) > 0) {
369	        continue;
370	      }
371	      // BFS 收集本环所有像素
372	      std::vector<Pixel> ring;
373	      std::queue<Pixel> bfs;
374	      bfs.push(seed);
375	      visited_orphan.insert(seed);
376	      while (!bfs.empty()) {
377	        const Pixel cur = bfs.front();
378	        bfs.pop();
379	        ring.push_back(cur);
380	        for (int i = 0; i < 8; ++i) {
381	          const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
382	          if (!skeleton.GetValue(nb.col, nb.row) ||
383	              visited_orphan.count(nb) > 0 ||
384	              feature_set.count(nb) > 0) {
385	            continue;
386	          }
387	          visited_orphan.insert(nb);
388	          bfs.push(nb);
389	        }
390	      }
391	      if (ring.size() < 3) {
392	        continue;  // 过短环不应出现，防御性跳过
393	      }
394	      // 在环上任取两个像素作为 RoadNode，环切成两段。
395	      // 简化：取 ring[0] 与 ring[ring.size()/2]。
396	      const Pixel n_a = ring.front();
397	      const Pixel n_b = ring[ring.size() / 2];
398	      auto add_node = [&](const Pixel& p) {
399	        if (pixel_to_node_id.count(p) > 0) {
400	          return;
401	        }
402	        const WorldCoord w =
403	            PixelToWorld(PixelCoord{static_cast<double>(p.col),
404	                                    static_cast<double>(p.row)},
405	                         map_info);
406	        catalog::RoadNode node;
407	        node.id = "rn_" + std::to_string(p.col) + "_" + std::to_string(p.row);
408	        node.x = w.x;
409	        node.y = w.y;
410	        catalog.road_nodes.push_back(node);
411	        pixel_to_node_id[p] = node.id;
412	        feature_set.insert(p);
413	      };
414	      add_node(n_a);
415	      add_node(n_b);
416	      // 在环上从 n_a 沿两个方向 BFS/追踪到 n_b。简化：直接追踪有序路径。
417	      // 构造环像素的相邻列表，然后从 n_a 走两条方向到 n_b。
418	      auto trace_on_ring = [&](const Pixel& from, const Pixel& first,
419	                               const Pixel& target) {
420	        std::vector<Pixel> path{from, first};
421	        Pixel prev = from;
422	        Pixel cur = first;
423	        const size_t limit = ring.size() + 8;
424	        while (!(cur == target) && path.size() <= limit) {
425	          // 选非 prev 的环邻居
426	          Pixel next{-1, -1};
427	          int found = 0;
428	          for (int i = 0; i < 8; ++i) {
429	            const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
430	            if (nb == prev) continue;
431	            if (!skeleton.GetValue(nb.col, nb.row)) continue;
432	            if (std::find(ring.begin(), ring.end(), nb) == ring.end()) continue;
433	            next = nb;
434	            ++found;
435	          }
436	          if (found == 0) break;
437	          prev = cur;
438	          cur = next;
439	          path.push_back(cur);
440	        }
441	        return path;
442	      };
443	      // n_a 的两个环邻居
444	      std::vector<Pixel> a_nbrs;
445	      for (int i = 0; i < 8; ++i) {
446	        const Pixel nb{n_a.col + kDCol[i], n_a.row + kDRow[i]};
447	        if (skeleton.GetValue(nb.col, nb.row) &&
448	            std::find(ring.begin(), ring.end(), nb) != ring.end() &&
449	            !(nb == n_b)) {
450	          a_nbrs.push_back(nb);
451	        }
452	      }
453	      for (const Pixel& first : a_nbrs) {
454	        const std::vector<Pixel> path = trace_on_ring(n_a, first, n_b);
455	        if (path.size() >= 2 && path.back() == n_b) {
456	          PixelEdge pe;
457	          pe.from = n_a;
458	          pe.to = n_b;
459	          pe.polyline_px = path;
460	          pixel_edges.push_back(std::move(pe));
461	        }
462	      }
463	    }
464	  }
465	
466	  // 边去重：(from_id, to_id, polyline_size) 三元组 + 检查双向重复。
467	  {
468	    std::vector<PixelEdge> unique_edges;
469	    for (const auto& e : pixel_edges) {
470	      bool dup = false;
471	      for (const auto& u : unique_edges) {
472	        if (e.from == u.from && e.to == u.to &&
473	            e.polyline_px.size() == u.polyline_px.size()) {
474	          dup = true;
475	          break;
476	        }
477	        // 反向同边（A->B 与 B->A 折线等长且首尾对应）
478	        if (e.from == u.to && e.to == u.from &&
479	            e.polyline_px.size() == u.polyline_px.size()) {
480	          // 验证首像素匹配（同一条几何链）
481	          if (e.polyline_px.front() == u.polyline_px.back() &&
482	              e.polyline_px.back() == u.polyline_px.front()) {
483	            dup = true;
484	            break;
485	          }
486	        }
487	      }
488	      if (!dup) {
489	        unique_edges.push_back(e);
490	      }
491	    }
492	    pixel_edges = std::move(unique_edges);
493	  }
494	
495	  // ---- 第三步：转换为 CatalogStationEdge（世界坐标 polyline + 累加距离）----
496	  for (const PixelEdge& pe : pixel_edges) {
497	    const auto it_from = pixel_to_node_id.find(pe.from);
498	    const auto it_to = pixel_to_node_id.find(pe.to);
499	    if (it_from == pixel_to_node_id.end() || it_to == pixel_to_node_id.end()) {
500	      continue;  // 防御：未注册的端点跳过
501	    }
502	    catalog::CatalogStationEdge edge;
503	    edge.from = it_from->second;
504	    edge.to = it_to->second;
505	    edge.bidirectional = true;
506	    edge.enabled = true;
507	    edge.polyline.reserve(pe.polyline_px.size());
508	    for (const Pixel& p : pe.polyline_px) {
509	      const WorldCoord w =
510	          PixelToWorld(PixelCoord{static_cast<double>(p.col),
511	                                  static_cast<double>(p.row)},
512	                       map_info);
513	      edge.polyline.emplace_back(w.x, w.y);
514	    }
515	    edge.distance_m = PolylineLength(edge.polyline);
516	    catalog.edges.push_back(std::move(edge));
517	  }
518	
519	  // ---- 第四步：站点吸附与边拆分 ----
520	  for (const AnchorStation& anchor : anchors) {
521	    if (catalog.edges.empty()) {
522	      result.error_message =
523	          "no edges available to snap station " + anchor.id;
524	      return result;
525	    }
526	    // 找到最近边及其投影点
527	    size_t best_edge_idx = std::numeric_limits<size_t>::max();
528	    ProjectionResult best_proj;
529	    for (size_t i = 0; i < catalog.edges.size(); ++i) {
530	      const auto& edge = catalog.edges[i];
531	      const ProjectionResult proj =
532	          ProjectToPolyline(anchor.x, anchor.y, edge.polyline);
533	      if (proj.distance < best_proj.distance) {
534	        best_proj = proj;
535	        best_edge_idx = i;
536	      }
537	    }
538	    if (best_edge_idx == std::numeric_limits<size_t>::max()) {
539	      result.error_message = "no valid edge for station " + anchor.id;
540	      return result;
541	    }
542	    if (best_proj.distance > config.max_snap_dist_m) {
543	      std::ostringstream oss;
544	      oss << "Station " << anchor.id
545	          << " is too far from skeleton: " << best_proj.distance << "m";
546	      result.error_message = oss.str();
547	      return result;
548	    }
549	
550	    // 将站点作为图节点（id = anchor.id，世界坐标采用投影点使节点落在
551	    // 骨架上——这样 SkeletonPlanner 沿折线循迹时能精确到站点）。
552	    catalog::Station st;
553	    st.id = anchor.id;
554	    st.x = best_proj.px;
555	    st.y = best_proj.py;
556	    st.yaw = anchor.yaw;
557	    catalog.stations.push_back(st);
558	
559	    // 拆分最近边：U -> V 变 U -> anchor -> V
560	    catalog::CatalogStationEdge original =
561	        catalog.edges[best_edge_idx];
562	    // 构造两段 polyline
563	    std::vector<std::pair<double, double>> poly_a;  // U -> proj
564	    std::vector<std::pair<double, double>> poly_b;  // proj -> V
565	    const size_t seg = best_proj.segment_index;
566	    const std::pair<double, double> proj_pt{best_proj.px, best_proj.py};
567	    // poly_a: polyline[0..seg] + proj_pt
568	    for (size_t i = 0; i <= seg; ++i) {
569	      poly_a.push_back(original.polyline[i]);
570	    }
571	    // 若 proj_pt 与末端点不同则补上（t<1 时需要）
572	    if (best_proj.segment_t < 1.0 - 1e-9 ||
573	        poly_a.back() != proj_pt) {
574	      if (std::hypot(poly_a.back().first - proj_pt.first,
575	                     poly_a.back().second - proj_pt.second) > 1e-9) {
576	        poly_a.push_back(proj_pt);
577	      }
578	    }
579	    // poly_b: proj_pt + polyline[seg+1..end]
580	    poly_b.push_back(proj_pt);
581	    for (size_t i = seg + 1; i < original.polyline.size(); ++i) {
582	      poly_b.push_back(original.polyline[i]);
583	    }
584	    // 清理 poly_b 起点：若 proj_pt 恰等于 polyline[seg+1] 则跳过重复
585	    if (poly_b.size() >= 2 &&
586	        std::hypot(poly_b[0].first - poly_b[1].first,
587	                   poly_b[0].second - poly_b[1].second) < 1e-9) {
588	      poly_b.erase(poly_b.begin());
589	    }
590	
591	    // 移除原边，加入两段新边
592	    catalog.edges.erase(catalog.edges.begin() +
593	                        static_cast<long>(best_edge_idx));
594	    if (poly_a.size() >= 2) {
595	      catalog::CatalogStationEdge e1;
596	      e1.from = original.from;
597	      e1.to = anchor.id;
598	      e1.bidirectional = original.bidirectional;
599	      e1.enabled = original.enabled;
600	      e1.polyline = std::move(poly_a);
601	      e1.distance_m = PolylineLength(e1.polyline);
602	      catalog.edges.push_back(std::move(e1));
603	    } else {
604	      // 投影点恰是端点 U：站点直接替代 U，但 schema 要求 from!=to。
605	      // 防御：跳过该段（意味着 anchor 与 U 重合，anchor 站点应替代 U
606	      // 的节点身份——但我们已将 anchor 作为新站点，需要至少保留 anchor
607	      // 的接入）。
608	      // 此时若 poly_b 也不存在，则 anchor 成为孤立站点，连通性校验会失败。
609	      // 为容错，把 U 节点的所有其他边重定向到 anchor。
610	      for (auto& e : catalog.edges) {
611	        if (e.from == original.from) e.from = anchor.id;
612	        if (e.to == original.from) e.to = anchor.id;
613	      }
614	    }
615	    if (poly_b.size() >= 2) {
616	      catalog::CatalogStationEdge e2;
617	      e2.from = anchor.id;
618	      e2.to = original.to;
619	      e2.bidirectional = original.bidirectional;
620	      e2.enabled = original.enabled;
621	      e2.polyline = std::move(poly_b);
622	      e2.distance_m = PolylineLength(e2.polyline);
623	      catalog.edges.push_back(std::move(e2));
624	    } else {
625	      // 投影点恰是端点 V：同上重定向。
626	      for (auto& e : catalog.edges) {
627	        if (e.from == original.to) e.from = anchor.id;
628	        if (e.to == original.to) e.to = anchor.id;
629	      }
630	    }
631	  }
632	
633	  // ---- 第五步：连通性校验 ----
634	  if (catalog.stations.size() >= 2) {
635	    const std::string& base = catalog.stations[0].id;
636	    for (size_t i = 1; i < catalog.stations.size(); ++i) {
637	      const std::string& target = catalog.stations[i].id;
638	      const auto path = catalog::FindRoutePath(catalog, base, target);
639	      if (!path.has_value()) {
640	        result.error_message =
641	            "Map network is disconnected: station " + target +
642	            " cannot reach " + base;
643	        return result;
644	      }
645	    }
646	  }
647	
648	  // ---- 第六步：schema 校验 ----
649	  std::string validation_error;
650	  if (!catalog::ValidateStationCatalog(catalog, &validation_error)) {
651	    result.error_message =
652	        "generated catalog failed validation: " + validation_error;
653	    return result;
654	  }
655	
656	  result.success = true;
657	  return result;
658	}
659	
660	}  // namespace amr_dispatcher_core::planning
