1	#include "amr_dispatcher_core/planning/topology_graph_builder.hpp"
2	
3	#include <gtest/gtest.h>
4	
5	#include <algorithm>
6	#include <cmath>
7	#include <cstdint>
8	#include <string>
9	#include <vector>
10	
11	namespace amr_dispatcher_core::planning {
12	namespace {
13	
14	constexpr double kResolution = 0.05;  // 米/像素
15	
16	MapGrid MakeMapInfo(uint32_t width, uint32_t height, double resolution) {
17	  MapGrid grid;
18	  grid.width = width;
19	  grid.height = height;
20	  grid.resolution = resolution;
21	  grid.origin_x = 0.0;
22	  grid.origin_y = 0.0;
23	  grid.origin_yaw = 0.0;
24	  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height),
25	                   kCellFree);
26	  return grid;
27	}
28	
29	BinaryGrid MakeSkeleton(uint32_t width, uint32_t height) {
30	  BinaryGrid grid;
31	  grid.width = width;
32	  grid.height = height;
33	  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height), 0);
34	  return grid;
35	}
36	
37	// 在世界坐标 (x, y) 处构造一个站点。
38	AnchorStation MakeAnchor(const std::string& id, double x, double y,
39	                         const std::string& type = "normal") {
40	  AnchorStation a;
41	  a.id = id;
42	  a.x = x;
43	  a.y = y;
44	  a.type = type;
45	  return a;
46	}
47	
48	// 沿 (col0,row) -> (col1,row) 填充水平骨架线。
49	void DrawHLine(BinaryGrid& grid, int row, int col0, int col1) {
50	  for (int col = col0; col <= col1; ++col) {
51	    grid.SetValue(col, row, 1);
52	  }
53	}
54	
55	// 沿 (col,row0) -> (col,row1) 填充垂直骨架线。
56	void DrawVLine(BinaryGrid& grid, int col, int row0, int row1) {
57	  for (int row = row0; row <= row1; ++row) {
58	    grid.SetValue(col, row, 1);
59	  }
60	}
61	
62	// 在骨架上找到 id 为 station_id 的 Station 索引，未找到返回 -1。
63	int StationIndex(const catalog::StationCatalog& catalog,
64	                 const std::string& station_id) {
65	  for (size_t i = 0; i < catalog.stations.size(); ++i) {
66	    if (catalog.stations[i].id == station_id) {
67	      return static_cast<int>(i);
68	    }
69	  }
70	  return -1;
71	}
72	
73	// ---------------------------------------------------------------------------
74	// 用例 1：直走廊 + 两端站点
75	//   骨架：一行 20 像素直线。两端各有一个站点。断言产生 2 个站点，原边被拆
76	//   分为 2 条子边（或者通过 road_node 中转），FindRoutePath 可寻路。
77	// ---------------------------------------------------------------------------
78	TEST(TopologyGraphBuilderTest,
79	     StraightCorridor_EndpointStations_Reachable) {
80	  // 像素宽度 20 -> 1.0m。骨架直线 row=5，col 0..19。
81	  const MapGrid map_info = MakeMapInfo(20, 11, kResolution);
82	  BinaryGrid skeleton = MakeSkeleton(20, 11);
83	  DrawHLine(skeleton, 5, 0, 19);
84	
85	  // 站点放在骨架两端附近（在 max_snap_dist 内）。
86	  std::vector<AnchorStation> anchors;
87	  anchors.push_back(MakeAnchor("s_left", 0.025, 0.275));   // 近 (0,5)
88	  anchors.push_back(MakeAnchor("s_right", 0.975, 0.275));  // 近 (19,5)
89	
90	  TopologyBuilderConfig config;
91	  config.max_snap_dist_m = 2.0;
92	  config.map_hash = "test_hash_1";
93	  config.graph_version = "v1";
94	
95	  const TopologyBuildResult result =
96	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
97	
98	  ASSERT_TRUE(result.success) << result.error_message;
99	  ASSERT_EQ(result.catalog.stations.size(), 2u);
100	  EXPECT_EQ(result.catalog.map_hash, "test_hash_1");
101	  EXPECT_EQ(result.catalog.graph_version, "v1");
102	
103	  // 两个站点之间存在可达路径（直线上经过拆分后的中间 road_node）。
104	  const auto path = catalog::FindRoutePath(result.catalog, "s_left", "s_right");
105	  ASSERT_TRUE(path.has_value()) << "两站点之间必须可达";
106	
107	  // 路径上的边应携带 polyline 折线（至少一条边应有 >=2 折线点）。
108	  bool any_polyline = false;
109	  for (const auto& edge : result.catalog.edges) {
110	    if (edge.polyline.size() >= 2) {
111	      any_polyline = true;
112	      break;
113	    }
114	  }
115	  EXPECT_TRUE(any_polyline) << "至少一条边应保留骨架折线";
116	}
117	
118	// ---------------------------------------------------------------------------
119	// 用例 2：L 弯走廊 + 中段充电桩站点
120	//   骨架 L 形：水平段 (0,10)->(39,10) + 垂直段 (39,10)->(39,30)。
121	//   拐角 (39,10) 处应产生 road_node；水平段中段的充电桩站点吸附后原边拆分。
122	// ---------------------------------------------------------------------------
123	TEST(TopologyGraphBuilderTest,
124	     LCornerCorridor_ChargeStationSplitsEdge) {
125	  const MapGrid map_info = MakeMapInfo(40, 31, kResolution);
126	  BinaryGrid skeleton = MakeSkeleton(40, 31);
127	  DrawHLine(skeleton, 10, 0, 39);
128	  DrawVLine(skeleton, 39, 10, 30);
129	
130	  // 充电桩站点位于水平段中段 (20,10) 附近（世界 y = (10+0.5)*0.05 = 0.525）。
131	  std::vector<AnchorStation> anchors;
132	  anchors.push_back(MakeAnchor("s_end_a", 0.025, 0.525));    // 水平端
133	  anchors.push_back(MakeAnchor("s_end_b", 1.975, 1.525));    // 垂直端 (39,30)
134	  anchors.push_back(MakeAnchor("charge_1", 1.025, 0.525, "charge"));  // (20,10)
135	
136	  TopologyBuilderConfig config;
137	  config.max_snap_dist_m = 2.0;
138	  config.map_hash = "test_hash_2";
139	  config.graph_version = "v1";
140	
141	  const TopologyBuildResult result =
142	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
143	
144	  ASSERT_TRUE(result.success) << result.error_message;
145	  ASSERT_EQ(result.catalog.stations.size(), 3u);
146	
147	  // 充电桩应作为图节点。
148	  const int charge_idx = StationIndex(result.catalog, "charge_1");
149	  ASSERT_GE(charge_idx, 0) << "charge_1 必须存在于 stations 中";
150	
151	  // 原"水平长边"必须被 charge_1 拆分为两段——即不存在跨越整个水平臂的边。
152	  // 即 s_end_a 与拐角 road_node 之间不存在直接边（必须经过 charge_1）。
153	  // 找一个含 "charge_1" 的边（连接 charge_1 到左侧或拐角）。
154	  bool edge_via_charge = false;
155	  for (const auto& edge : result.catalog.edges) {
156	    if (edge.from == "charge_1" || edge.to == "charge_1") {
157	      edge_via_charge = true;
158	      break;
159	    }
160	  }
161	  EXPECT_TRUE(edge_via_charge) << "应存在以 charge_1 为端点的边";
162	
163	  // 全部站点间可达。
164	  const auto path_ab =
165	      catalog::FindRoutePath(result.catalog, "s_end_a", "s_end_b");
166	  ASSERT_TRUE(path_ab.has_value());
167	  const auto path_ac =
168	      catalog::FindRoutePath(result.catalog, "s_end_a", "charge_1");
169	  ASSERT_TRUE(path_ac.has_value());
170	  const auto path_bc =
171	      catalog::FindRoutePath(result.catalog, "charge_1", "s_end_b");
172	  ASSERT_TRUE(path_bc.has_value());
173	
174	  // charge_1 -> s_end_b 路径必须途经拐角（polyline 应呈 L 形）。
175	  // 找一条以 charge_1 为端点的边，要求其 polyline 中存在 y 接近 0.525
176	  // 的拐点（拐角 (39,10) -> 世界 (1.975, 0.525)）。
177	  bool found_L_shape = false;
178	  for (const auto& edge : result.catalog.edges) {
179	    if (edge.polyline.size() < 3) {
180	      continue;
181	    }
182	    // L 形折线：拐角点应在折线中间而非首尾。
183	    for (size_t i = 1; i + 1 < edge.polyline.size(); ++i) {
184	      const auto& p = edge.polyline[i];
185	      if (std::abs(p.first - 1.975) < 0.05 &&
186	          std::abs(p.second - 0.525) < 0.05) {
187	        found_L_shape = true;
188	        break;
189	      }
190	    }
191	    if (found_L_shape) break;
192	  }
193	  EXPECT_TRUE(found_L_shape)
194	      << "L 形折线应在中间包含拐角点 (~1.975, 0.525)";
195	}
196	
197	// ---------------------------------------------------------------------------
198	// 用例 3：站点距骨架过远 -> 构建失败
199	// ---------------------------------------------------------------------------
200	TEST(TopologyGraphBuilderTest, FarStation_BuildFails) {
201	  const MapGrid map_info = MakeMapInfo(20, 20, kResolution);
202	  BinaryGrid skeleton = MakeSkeleton(20, 20);
203	  DrawHLine(skeleton, 5, 0, 19);  // y = (5+0.5)*0.05 = 0.275m
204	
205	  std::vector<AnchorStation> anchors;
206	  anchors.push_back(MakeAnchor("s_ok", 0.025, 0.275));
207	  // 远站点：x 与骨架重合，但 y 偏离 5.0m
208	  anchors.push_back(MakeAnchor("s_far", 0.5, 5.275));
209	
210	  TopologyBuilderConfig config;
211	  config.max_snap_dist_m = 2.0;
212	  config.map_hash = "h3";
213	  config.graph_version = "v1";
214	
215	  const TopologyBuildResult result =
216	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
217	
218	  EXPECT_FALSE(result.success);
219	  EXPECT_NE(result.error_message.find("too far"), std::string::npos)
220	      << "错误信息应包含 'too far'，实际：" << result.error_message;
221	  EXPECT_NE(result.error_message.find("s_far"), std::string::npos)
222	      << "错误信息应包含失败站点 id，实际：" << result.error_message;
223	}
224	
225	// ---------------------------------------------------------------------------
226	// 用例 4：两个不连通走廊 -> 构建失败（disconnected）
227	// ---------------------------------------------------------------------------
228	TEST(TopologyGraphBuilderTest, DisconnectedIslands_BuildFails) {
229	  const MapGrid map_info = MakeMapInfo(40, 20, kResolution);
230	  BinaryGrid skeleton = MakeSkeleton(40, 20);
231	  DrawHLine(skeleton, 5, 0, 19);    // 左孤岛
232	  DrawHLine(skeleton, 15, 20, 39);  // 右孤岛（与左孤岛无骨架连接）
233	
234	  std::vector<AnchorStation> anchors;
235	  anchors.push_back(MakeAnchor("s_a", 0.025, 0.275));   // 左岛
236	  anchors.push_back(MakeAnchor("s_b", 1.975, 0.775));   // 右岛
237	
238	  TopologyBuilderConfig config;
239	  config.max_snap_dist_m = 2.0;
240	  config.map_hash = "h4";
241	  config.graph_version = "v1";
242	
243	  const TopologyBuildResult result =
244	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
245	
246	  EXPECT_FALSE(result.success);
247	  EXPECT_NE(result.error_message.find("disconnected"), std::string::npos)
248	      << "错误信息应包含 'disconnected'，实际：" << result.error_message;
249	}
250	
251	// ---------------------------------------------------------------------------
252	// 用例 5：真实折线累加长度
253	//   构造骨架：(0,0) -> (0,3) -> (4,3)。折线实际长度 = 3 + 4 = 7 像素。
254	//   在 0.05m/像素 下 = 0.35m。但用例要求 7m——改用 res=1.0m。
255	//   为简化测试，使用 res=1.0m 验证累加几何长度 = 7m。
256	// ---------------------------------------------------------------------------
257	TEST(TopologyGraphBuilderTest, PolylineAccumulatedLength_NotStraightLine) {
258	  // res = 1.0 m/px。骨架：(0,5) -> (4,5) 水平 4 像素 + (4,5) -> (4,8) 垂直
259	  // 3 像素，L 形折线总长度 = 4 + 3 = 7m，而起点终点直线距离 = 5m。
260	  const MapGrid map_info = MakeMapInfo(5, 9, 1.0);
261	  BinaryGrid skeleton = MakeSkeleton(5, 9);
262	  DrawHLine(skeleton, 5, 0, 4);
263	  DrawVLine(skeleton, 4, 5, 8);
264	
265	  // 站点放在两端附近（世界坐标：(0,5)->(0.5,5.5)，(4,8)->(4.5,8.5)）。
266	  std::vector<AnchorStation> anchors;
267	  anchors.push_back(MakeAnchor("s_a", 0.5, 5.5));
268	  anchors.push_back(MakeAnchor("s_b", 4.5, 8.5));
269	
270	  TopologyBuilderConfig config;
271	  config.max_snap_dist_m = 5.0;
272	  config.map_hash = "h5";
273	  config.graph_version = "v1";
274	
275	  const TopologyBuildResult result =
276	      BuildTopologyCatalog(skeleton, map_info, anchors, config);
277	
278	  ASSERT_TRUE(result.success) << result.error_message;
279	
280	  // 找 s_a -> s_b 路径，断言其累加距离接近 7m，而非 5m 直线距离。
281	  const auto path =
282	      catalog::FindRoutePath(result.catalog, "s_a", "s_b");
283	  ASSERT_TRUE(path.has_value());
284	
285	  // 路径距离由 catalog::EstimateRouteDistance 给出（经过中间拐角节点）。
286	  const auto dist =
287	      catalog::EstimateRouteDistance(result.catalog, "s_a", "s_b");
288	  ASSERT_TRUE(dist.has_value());
289	  // 累加长度应约等于 4 + 3 = 7m（容差 0.2m 吸收像素取整）。
290	  EXPECT_NEAR(*dist, 7.0, 0.2)
291	      << "折线累加长度应为 ~7m，实际 " << *dist << "m";
292	
293	  // 至少一条边上的累加距离大于其端点直线距离（验证 polyline 累积而非
294	  // 直线距离）。
295	  bool edge_with_accumulated = false;
296	  for (const auto& edge : result.catalog.edges) {
297	    if (edge.polyline.size() >= 3) {
298	      // 计算折线累加长度
299	      double accum = 0.0;
300	      for (size_t i = 1; i < edge.polyline.size(); ++i) {
301	        const auto& p0 = edge.polyline[i - 1];
302	        const auto& p1 = edge.polyline[i];
303	        accum += std::hypot(p1.first - p0.first, p1.second - p0.second);
304	      }
305	      // 直线距离
306	      const auto& p_first = edge.polyline.front();
307	      const auto& p_last = edge.polyline.back();
308	      const double straight = std::hypot(p_last.first - p_first.first,
309	                                         p_last.second - p_first.second);
310	      if (accum > straight + 0.5) {
311	        edge_with_accumulated = true;
312	        break;
313	      }
314	    }
315	  }
316	  EXPECT_TRUE(edge_with_accumulated)
317	      << "至少一条边的折线累加长度应大于端点直线距离";
318	}
